import { useState } from "react";
import "./App.css";

function App() {
    const [transactions, setTransactions] = useState([]);
    const [balance, setBalance] = useState(0);

    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances balance={balance} />
            <TradeForm />
            <DepositAndWithdrawalForm />
            <TransactionTable />
            <TradesTable />
        </div>
    );
}

function Balances({ balance }) {
    return (
        <div>
            <label>Account Balance</label>
            <input type="text" disabled value={balance} />
        </div>
    );
}

function TradeForm() {
    const [transactionType, setTransactionType] = useState("buy");

    function handleSubmit(e, action) {
        e.preventDefault();
        console.log(action);
    }

    return (
        <form className="form">
            <div>
                <input
                    type="radio"
                    id="buy"
                    name="transaction_type"
                    value="buy"
                />
                <label htmlFor="buy">Buy</label>
                <input
                    type="radio"
                    id="sell"
                    name="transaction_type"
                    value="sell"
                />
                <label htmlFor="sell">Sell</label>
            </div>
            <div>
                <label>Stock</label>
                <input type="text" />
            </div>
            <div>
                <label>Shares</label>
                <input type="text" />
            </div>
            <div>
                <label>Price</label>
                <input type="text" />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled />
            </div>
            <button>Buy</button>
        </form>
    );
}

function DepositAndWithdrawalForm() {
    return (
        <form className="form">
            <div>
                <label>Amount</label>
                <input type="text" />
            </div>
            <button>Deposit</button>
            <button>Withdraw</button>
        </form>
    );
}

function TransactionTable() {
    return (
        <div>
            <h2>Transactions</h2>
            <table></table>
        </div>
    );
}

function TradesTable() {
    return (
        <div>
            <h2>Trades</h2>
            <table></table>
        </div>
    );
}

export default App;
